cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int kD, int kH, int kW,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int groups, int icPerGroup, int ocPerGroup,
    int Dout, int Hout, int Wout,
    int CcPerBlock, int PVec, int Threads)
{
    extern __shared__ unsigned char smem_raw[];
    T* sW_ptr = reinterpret_cast<T*>(smem_raw);

    const int tid = threadIdx.x;

    const int n      = blockIdx.z;
    const int c_tile = blockIdx.y;
    const int c_base = c_tile * CcPerBlock;

    const int P_total = Dout * Hout * Wout;
    const int PTile   = Threads * PVec;
    const int p_block = blockIdx.x * PTile;

    // Global tensors via CuTe
    int64_t sXn = (int64_t)Cin * D * H * Win;
    int64_t sXc = (int64_t)D * H * Win;
    int64_t sXd = (int64_t)H * Win;
    int64_t sXh = (int64_t)Win;

    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(Cin, D, H, Win),
        make_stride(sXc, sXd, sXh, Int<1>{})
    );

    int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
    int64_t sYc = (int64_t)Dout * Hout * Wout;
    int64_t sYd = (int64_t)Hout * Wout;
    int64_t sYh = (int64_t)Wout;

    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(Cout, Dout, Hout, Wout),
        make_stride(sYc, sYd, sYh, Int<1>{})
    );

    // Weight tensor: (Cin, ocPerGroup, kD, kH, kW)
    int64_t sWi  = (int64_t)ocPerGroup * kD * kH * kW;
    int64_t sWo  = (int64_t)kD * kH * kW;
    int64_t sWd  = (int64_t)kH * kW;
    int64_t sWh  = (int64_t)kW;

    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(Cin, ocPerGroup, kD, kH, kW),
        make_stride(sWi, sWo, sWd, sWh, Int<1>{})
    );

    // Shared weight cache: (CcPerBlock, icPerGroup, kD, kH, kW)
    int64_t s_sWi = (int64_t)kD * kH * kW;
    int64_t s_sWd = (int64_t)kH * kW;
    int64_t s_sWh = (int64_t)kW;
    int64_t sW_cc_stride = (int64_t)icPerGroup * kD * kH * kW;

    auto sW = make_tensor(
        make_smem_ptr(sW_ptr),
        make_shape(CcPerBlock, icPerGroup, kD, kH, kW),
        make_stride(sW_cc_stride, s_sWi, s_sWd, s_sWh, Int<1>{})
    );

    // Cooperative load of weight chunk for this c_tile
    int total_load = CcPerBlock * icPerGroup * kD * kH * kW;
    for (int idx = tid; idx < total_load; idx += Threads) {
        int rem = idx;
        int kw_i = rem % kW; rem /= kW;
        int kh_i = rem % kH; rem /= kH;
        int kd_i = rem % kD; rem /= kD;
        int ic_l = rem % icPerGroup; rem /= icPerGroup;
        int cc   = rem;

        int c = c_base + cc;
        T wval = T(0);
        if (c < Cout) {
            int group   = c / ocPerGroup;
            int oc_local = c - group * ocPerGroup;
            int ic_base = group * icPerGroup;
            int ic = ic_base + ic_l;
            wval = mW(ic, oc_local, kd_i, kh_i, kw_i);
        }
        sW(cc, ic_l, kd_i, kh_i, kw_i) = wval;
    }
    __syncthreads();

    // Decode output positions for this thread
    int p_idx[8];
    int od_arr[8], oh_arr[8], ow_arr[8];
    bool valid[8];

    for (int i = 0; i < PVec; ++i) {
        int p = p_block + tid + i * Threads;
        p_idx[i] = p;
        if (p < P_total) {
            int od = p / (Hout * Wout);
            int rem = p - od * Hout * Wout;
            int oh = rem / Wout;
            int ow = rem - oh * Wout;
            od_arr[i] = od;
            oh_arr[i] = oh;
            ow_arr[i] = ow;
            valid[i] = true;
        } else {
            od_arr[i] = 0; oh_arr[i] = 0; ow_arr[i] = 0;
            valid[i] = false;
        }
    }

    float acc[4][8]; // [cc][i], max CcPerBlock=4, max PVec=8
    for (int cc = 0; cc < CcPerBlock; ++cc) {
        int c = c_base + cc;
        float bval = 0.0f;
        if (B != nullptr && c < Cout) {
            bval = (float)B[c];
        }
        for (int i = 0; i < PVec; ++i) {
            acc[cc][i] = bval;
        }
    }

    for (int i = 0; i < PVec; ++i) {
        if (!valid[i]) continue;
        int od = od_arr[i];
        int oh = oh_arr[i];
        int ow = ow_arr[i];

        for (int cc = 0; cc < CcPerBlock; ++cc) {
            int c = c_base + cc;
            if (c >= Cout) continue;

            int group = c / ocPerGroup;
            int ic_base = group * icPerGroup;

            float local_acc = 0.0f;

            for (int ic_l = 0; ic_l < icPerGroup; ++ic_l) {
                int ic = ic_base + ic_l;

                for (int kd_i = 0; kd_i < kD; ++kd_i) {
                    int id_val = od + padD - kd_i;
                    if (id_val % strideD != 0) continue;
                    int id_idx = id_val / strideD;
                    if (id_idx < 0 || id_idx >= D) continue;

                    for (int kh_i = 0; kh_i < kH; ++kh_i) {
                        int ih_val = oh + padH - kh_i;
                        if (ih_val % strideH != 0) continue;
                        int ih_idx = ih_val / strideH;
                        if (ih_idx < 0 || ih_idx >= H) continue;

                        for (int kw_i = 0; kw_i < kW; ++kw_i) {
                            int iw_val = ow + padW - kw_i;
                            if (iw_val % strideW != 0) continue;
                            int iw_idx = iw_val / strideW;
                            if (iw_idx < 0 || iw_idx >= Win) continue;

                            float xval = (float)mX(ic, id_idx, ih_idx, iw_idx);
                            float wval = (float)sW(cc, ic_l, kd_i, kh_i, kw_i);
                            local_acc += xval * wval;
                        }
                    }
                }
            }
            acc[cc][i] += local_acc;
        }
    }

    for (int i = 0; i < PVec; ++i) {
        if (!valid[i]) continue;
        int od = od_arr[i];
        int oh = oh_arr[i];
        int ow = ow_arr[i];
        for (int cc = 0; cc < CcPerBlock; ++cc) {
            int c = c_base + cc;
            if (c >= Cout) continue;
            mY(c, od, oh, ow) = static_cast<T>(acc[cc][i]);
        }
    }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outpadD, int outpadH, int outpadW,
    int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA if provided");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must be [Cin, Cout/groups, kD, kH, kW]");

    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t D   = x.size(2);
    int64_t H   = x.size(3);
    int64_t Win = x.size(4);

    TORCH_CHECK(weight.size(0) == Cin, "weight.size(0) must equal Cin");
    int64_t ocPerGroup = weight.size(1);
    int64_t kD = weight.size(2);
    int64_t kH = weight.size(3);
    int64_t kW = weight.size(4);

    int64_t Cout = ocPerGroup * groups;
    int64_t icPerGroup = Cin / groups;

    TORCH_CHECK(strideD > 0 && strideH > 0 && strideW > 0, "strides must be > 0");
    TORCH_CHECK(padD >= 0 && padH >= 0 && padW >= 0, "padding must be >= 0");

    int64_t Dout = (D - 1) * strideD - 2 * padD + kD + outpadD;
    int64_t Hout = (H - 1) * strideH - 2 * padH + kH + outpadH;
    int64_t Wout = (Win - 1) * strideW - 2 * padW + kW + outpadW;
    TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    torch::Tensor b_c;
    const float* b_ptr = nullptr;
    if (bias.has_value()) {
        b_c = bias.value().contiguous();
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
        b_ptr = b_c.data_ptr<float>();
    }

    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

    // Choose tiling params
    int CcPerBlock = 2;
    if (Cout < CcPerBlock) CcPerBlock = (int)Cout;
    if (CcPerBlock < 1) CcPerBlock = 1;
    if (CcPerBlock > 4) CcPerBlock = 4;

    int PVec = 4;
    if (PVec > 8) PVec = 8;

    const int Threads = 128;

    int64_t P_total = Dout * Hout * Wout;
    int64_t PTile = (int64_t)Threads * PVec;

    dim3 block(Threads);
    dim3 grid(
        (unsigned)((P_total + PTile - 1) / PTile),
        (unsigned)((Cout + CcPerBlock - 1) / CcPerBlock),
        (unsigned)N
    );

    size_t shmem_bytes = (size_t)CcPerBlock * icPerGroup * kD * kH * kW * sizeof(float);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    if (shmem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(
            conv_transpose3d_kernel<float>,
            cudaFuncAttributeMaxDynamicSharedMemorySize,
            (int)shmem_bytes
        );
    }

    conv_transpose3d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_ptr,
        y.data_ptr<float>(),
        (int)N, (int)Cin, (int)D, (int)H, (int)Win,
        (int)Cout, (int)kD, (int)kH, (int)kW,
        strideD, strideH, strideW,
        padD, padH, padW,
        groups, (int)icPerGroup, (int)ocPerGroup,
        (int)Dout, (int)Hout, (int)Wout,
        CcPerBlock, PVec, Threads
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
