class ModelNew(nn.Module):
    """
    Transposed 3D convolution with asymmetric input and kernel sizes,
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(int(k) for k in kernel_size)
        self.stride = tuple(int(s) for s in stride)
        self.padding = tuple(int(p) for p in padding)
        self.output_padding = tuple(int(p) for p in output_padding)
        self.groups = int(groups)

        kD, kH, kW = self.kernel_size
        assert in_channels % groups == 0
        assert out_channels % groups == 0
        oc_per_group = out_channels // groups

        # Weight shape matches PyTorch ConvTranspose3d layout: [Cin, Cout/groups, kD, kH, kW]
        self.weight = nn.Parameter(torch.empty(in_channels, oc_per_group, kD, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels // self.groups
            for k in self.kernel_size:
                fan_in *= 1  # fan_in scaling handled below
            kD, kH, kW = self.kernel_size
            fan_in = (self.in_channels // self.groups) * kD * kH * kW
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.groups,
        )
